// Room "P2 ground bedroom" (interior designer's part): a 3 x 2 bedroom, box [36,2,19,38,4,20]. The bed is the focal
// piece: its head sits against the partition z18 (the west wall x35 is a window pair, so the head cannot go there).
// A barrel dresser with a lantern on its lid stands beside the foot; the x38 column and the cell past the foot stay
// clear, so the door at (38,18) walks to the bed. The lantern is standing (no ceiling block is built yet above y4).
import { B, layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { bedSet, dresser } from "../vocab.mjs";

export function build(g) {
  // the bed: foot at (36,2,20), head at (36,2,19) against the partition at z18
  bedSet(g, [36, 2, 20], "north", "red");

  // dresser: one barrel at (37,2,19) on the floor, its front toward the room (south)
  dresser(g, { x: 37, y: 2, z: 19, facing: "south", length: 1 });

  // a standing lantern on the barrel lid: light to every cell of the 3 x 2 room (lit 8+ at the feet)
  g.set(37, 3, 19, ...B.lantern(false));
}

